"use client";
import { useRef } from "react";
import { useScrollMotion, type ScrollMotionProps } from "./scroll-shared";
export interface SvgDrawPathProps extends ScrollMotionProps {
  path: string;
  viewBox?: string;
  stroke?: string;
  strokeWidth?: number;
  ghostOpacity?: number;
  label?: string;
  reverse?: boolean;
}
export function SvgDrawPath({
  path,
  viewBox = "0 0 800 500",
  stroke = "currentColor",
  strokeWidth = 3,
  ghostOpacity = 0.12,
  label = "Scroll drawing",
  reverse = false,
  ...props
}: SvgDrawPathProps) {
  const root = useRef<HTMLDivElement>(null);
  useScrollMotion(
    root,
    props,
    ({ progress: p }) => {
      const line = root.current!.querySelector<SVGPathElement>("[data-scroll-path]")!;
      line.style.strokeDashoffset = String(reverse ? -(1 - p) : 1 - p);
    },
    `${path}:${reverse}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="svg-draw-path"
      className={props.className}
      style={{ width: "100%", height: "100%", ...props.style }}
    >
      <svg
        role="img"
        aria-label={label}
        viewBox={viewBox}
        style={{ display: "block", width: "100%", height: "100%", overflow: "visible" }}
        fill="none"
        stroke={stroke}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d={path} opacity={ghostOpacity} />
        <path
          data-scroll-path=""
          d={path}
          pathLength={1}
          strokeDasharray="1"
          strokeDashoffset="0"
        />
      </svg>
    </div>
  );
}
